function kurroRequest(params){return new Promise((resolve,reject)=>{const cb='kurro_'+Date.now()+'_'+Math.random().toString(36).slice(2);const script=document.createElement('script');const timer=setTimeout(()=>{delete window[cb];script.remove();reject(new Error('Tiempo de espera agotado'))},12000);window[cb]=data=>{clearTimeout(timer);delete window[cb];script.remove();data&&data.ok?resolve(data.result):reject(new Error('Respuesta no válida'))};script.onerror=()=>{clearTimeout(timer);delete window[cb];script.remove();reject(new Error('No se pudo conectar'))};params.callback=cb;script.src=KURRO_API+'?'+new URLSearchParams(params).toString();document.body.appendChild(script)})}
function remotePlanningRow(row,index){const y=String(row[11]||'').trim().toUpperCase();let status=/REALIZADO|ACEPTADO|HECHO/.test(y)?'done':/EN PROCESO|PROCESO/.test(y)?'process':'open';return{activity:row[0]||'',category:row[1]||'Otros',frequency:row[2]||'',last:row[3]||'',next:row[4]||'',type:String(row[5]||'').toUpperCase(),owner:row[6]||'',provider:row[8]||'',status,action:row[9]||'',serverRow:index+2}}
function remotePendingRow(row,index,person,fileId){return{person,status:String(row[0]||'PENDIENTE').toUpperCase(),comments:row[1]||'',text:row[2]||'',priority:String(row[3]||'NORMAL').toUpperCase(),date:row[4]||'',updated:row[5]||'',closed:row[6]||'',serverRow:index+2,fileId}}
async function loadRemoteData(){try{const data=await kurroRequest({api:'data'});const planningValues=data.planning?.values||[];const planningRows=planningValues.slice(1).map((row,index)=>({row,index})).filter(x=>String(x.row[0]||'').trim()).map(x=>remotePlanningRow(x.row,x.index));if(planningRows.length)centerRows.splice(0,centerRows.length,...planningRows);const p=[];for(const source of [{data:data.miguel,person:'Miguel'},{data:data.properval,person:'Properval'}]){const values=source.data?.values||[];values.slice(1).filter(r=>String(r[2]||'').trim()).forEach((r,i)=>p.push(remotePendingRow(r,i,source.person,source.data.id)))}if(p.length)pendingRows.splice(0,pendingRows.length,...p);refreshKURROMetrics();renderCenter();renderPending()}catch(e){console.warn('No se pudo actualizar la vista',e)}}
let kurroPendingWrites=0;
let kurroRefreshInFlight=false;
function remoteWrite(request){kurroPendingWrites++;return request.finally(()=>{kurroPendingWrites--})}
function isEditingKURRO(){const active=document.activeElement;return active&&(['INPUT','TEXTAREA','SELECT'].includes(active.tagName)||active.isContentEditable)}
function showSyncToast(message){const toast=$('toast');if(!toast)return;toast.textContent=message;toast.classList.add('show');clearTimeout(window.kurroToastTimer);window.kurroToastTimer=setTimeout(()=>toast.classList.remove('show'),2200)}
function refreshKURROMetrics(){if($('center-metrics'))$('center-metrics').innerHTML=metric('Actividades registradas',centerRows.length,'Registro maestro')+metric('Pendientes de centro',centerRows.filter(r=>effectiveStatus(r)==='open').length,'Requieren seguimiento',true)+metric('En proceso',centerRows.filter(r=>effectiveStatus(r)==='process').length,'Acciones abiertas')+metric('Próximas revisiones',centerRows.filter(r=>r.next).length,'Con fecha definida');if($('pending-metrics'))$('pending-metrics').innerHTML=metric('Pendientes totales',pendingRows.filter(r=>r.status!=='REALIZADO').length,'Miguel + Properval')+metric('Con Miguel',pendingRows.filter(r=>r.person==='Miguel'&&r.status!=='REALIZADO').length,'Seguimiento activo')+metric('Con Properval',pendingRows.filter(r=>r.person==='Properval'&&r.status!=='REALIZADO').length,'Seguimiento activo')+metric('Con fecha objetivo',pendingRows.filter(r=>r.date&&r.status!=='REALIZADO').length,'Para priorizar')}
async function refreshKURROFromSheets(silent=false){if(kurroRefreshInFlight||kurroPendingWrites||isEditingKURRO())return;kurroRefreshInFlight=true;try{await loadRemoteData();if(!silent)showSyncToast('Datos actualizados desde Google Sheets')}finally{kurroRefreshInFlight=false}}
