$('delete-client-editor')?.addEventListener('click',deleteClientEditor);

function dashboardDate(value){const p=String(value||'').split('/');return p.length===3?new Date(`${p[2]}-${p[1]}-${p[0]}T23:59:59`):null}
function dashboardUrgent(){const now=new Date(),soon=new Date(now.getTime()+30*86400000),items=[];centerRows.forEach(r=>{const d=dashboardDate(r.next);if(d&&effectiveStatus(r)!=='done'&&d<=soon)items.push({kind:'Centro',title:r.activity,detail:d<now?'Vencida':`Revisión ${r.next}`,view:'center',rank:d<now?0:1,date:d})});pendingRows.forEach(r=>{const d=dashboardDate(r.date);if(d&&r.status!=='REALIZADO'&&d<=soon)items.push({kind:'Pendiente',title:r.text,detail:d<now?'Vencido':`Objetivo ${r.date}`,view:'pending',rank:r.priority==='ALTA'?0:1,date:d})});clientRows.forEach(r=>{const d=dashboardDate(r.date);if(d&&r.status!=='REALIZADO'&&d<=soon)items.push({kind:'Cliente',title:r.text,detail:d<now?'Vencido':`Objetivo ${r.date}`,view:'clients',rank:r.priority==='ALTA'?0:1,date:d})});return items.sort((a,b)=>a.rank-b.rank||a.date-b.date).slice(0,8)}
function dashboardGo(view){document.querySelector(`.nav-item[data-view="${view}"]`)?.click()}
function renderDashboard(){const metrics=$('dashboard-metrics');if(!metrics)return;const urgent=dashboardUrgent(),openCenter=centerRows.filter(r=>effectiveStatus(r)!=='done').length,openPending=pendingRows.filter(r=>r.status!=='REALIZADO').length,openClients=clientRows.filter(r=>r.status!=='REALIZADO').length;metrics.innerHTML=metric('Requieren atención',urgent.length,'Vencidos o próximos',urgent.some(x=>x.detail.includes('Vencid')))+metric('Pendientes del centro',openCenter,'Revisiones abiertas')+metric('Seguimientos',openPending,'Miguel y Properval')+metric('Con clientes',openClients,'Seguimientos abiertos');$('dashboard-urgent-count').textContent=`${urgent.length} avisos`;$('dashboard-urgent-list').innerHTML=urgent.length?urgent.map(x=>`<div class="dashboard-item"><span class="dashboard-kind">${x.kind}</span><div><strong>${x.title}</strong><small>${x.detail}</small></div></div>`).join(''):'<div class="dashboard-empty">No hay asuntos urgentes en los próximos 30 días.</div>';}
document.querySelector('[data-dashboard-refresh]')?.addEventListener('click',()=>{renderDashboard();refreshKURROFromSheets(false)});
document.querySelectorAll('.nav-item').forEach(b=>b.addEventListener('click',()=>{if(b.dataset.view==='dashboard')$('page-title').textContent='Resumen'}));
renderDashboard();
function pendingSortDate(value){const p=String(value||'').split('/');return p.length===3?new Date(`${p[2]}-${p[1]}-${p[0]}T23:59:59`).getTime():Number.MAX_SAFE_INTEGER}
function sortPendingRows(){const mode=$('pending-sort')?.value||'date';pendingRows.sort((a,b)=>{if(mode==='priority')return (a.priority==='ALTA'?0:1)-(b.priority==='ALTA'?0:1)||pendingSortDate(a.date)-pendingSortDate(b.date);if(mode==='updated')return pendingSortDate(b.updated)-pendingSortDate(a.updated);return pendingSortDate(a.date)-pendingSortDate(b.date)})}
const renderPendingWithName=renderPending;renderPending=function(){sortPendingRows();renderPendingWithName();if($('pending-heading'))$('pending-heading').textContent=window.person==='all'?'Todos los seguimientos':`Seguimientos con ${window.person}`};
document.querySelectorAll('.nav-item').forEach(b=>b.addEventListener('click',()=>{if(b.dataset.view==='pending')$('page-title').textContent='Seguimientos'}));
const renderDashboardWithLabels=renderDashboard;renderDashboard=function(){renderDashboardWithLabels();document.querySelectorAll('#dashboard-links strong').forEach(x=>{if(x.textContent==='Mis pendientes')x.textContent='Seguimientos'});document.querySelectorAll('#dashboard-links small').forEach(x=>{if(x.textContent==='Seguimientos personales')x.textContent='Temas y recordatorios'});if($('dashboard-metrics'))$('dashboard-metrics').innerHTML=$('dashboard-metrics').innerHTML.replaceAll('Mis pendientes','Seguimientos')};
renderDashboard();
document.querySelector('[data-new-client]')?.addEventListener('click',()=>openClientEditor());
document.querySelectorAll('.nav-item').forEach(b=>b.addEventListener('click',()=>{if(b.dataset.view==='clients')$('page-title').textContent='Seguimientos con clientes'}));
['pending-sort'].forEach(id=>$(id)?.addEventListener('input',renderPending));

// Dependencia: se muestra y se guarda sin añadir otra columna visual.
const baseOpenCenterEditorWithDependency=openCenterEditor;
openCenterEditor=function(index){baseOpenCenterEditorWithDependency(index);const r=centerRows[index];if(!r)return;$('edit-type').value=dependencyType(r);$('edit-provider').value=r.provider||'';syncDependencyEditor()};
$('edit-type')?.addEventListener('change',syncDependencyEditor);
const baseSaveCenterEditorWithDependency=saveCenterEditorFlexible;
saveCenterEditorFlexible=async function(){const index=centerEditorIndex,isNew=index===-1,r=isNew?{}:centerRows[index],type=$('edit-type')?.value||'',provider=$('edit-provider')?.value.trim()||'';await baseSaveCenterEditorWithDependency();const saved=isNew?centerRows[centerRows.length-1]:r;if(!saved)return;saved.type=type;saved.provider=provider;saveData();const columns={type:6,provider:9},writes=[];Object.entries({type,provider}).forEach(([field,value])=>{if(saved.serverRow)writes.push(kurroRequest({api:'updateCell',fileId:'1AiIsFZCyZVp4ERTi0ExreV10StjayEw9tLWv4W21foQ',sheetName:'Registro Maestro',row:saved.serverRow,column:columns[field],value}))});if(writes.length)remoteWrite(Promise.all(writes).catch(()=>{}))};
const dependencySaveButton=$('save-center-editor');if(dependencySaveButton){const replacement=dependencySaveButton.cloneNode(true);dependencySaveButton.replaceWith(replacement);replacement.addEventListener('click',saveCenterEditorFlexible)}
function normalizeLabels(){
  if($('pending-editor-title')&&$('pending-editor-title').textContent.includes('pendiente'))$('pending-editor-title').textContent=$('pending-editor-title').textContent.replaceAll('pendiente','seguimiento');
  if($('client-editor-title')&&$('client-editor-title').textContent.includes('pendiente'))$('client-editor-title').textContent=$('client-editor-title').textContent.replaceAll('pendiente','seguimiento');
  document.querySelectorAll('#client-table .empty').forEach(x=>x.textContent='No hay seguimientos con estos filtros. Pulsa «Registrar seguimiento» para añadir el primero.');
}
normalizeLabels();
function cleanInternalLabels(){document.querySelectorAll('#center-metrics *,#pending-metrics *,#dashboard-metrics *').forEach(el=>{if(el.children.length)return;if(el.textContent.includes('Registro maestro'))el.textContent=el.textContent.replaceAll('Registro maestro','Actividades del centro')})}
cleanInternalLabels();
new MutationObserver(cleanInternalLabels).observe(document.body,{subtree:true,childList:true});
document.querySelector('[data-quick-center]')?.addEventListener('click',()=>openNewCenterEditor());
document.querySelector('[data-quick-pending]')?.addEventListener('click',()=>openPendingEditor());
document.querySelector('[data-quick-client]')?.addEventListener('click',()=>openClientEditor());

// Cada cambio de pestaña vuelve a pintar su contenido con los datos actuales.
// Los filtros permanecen en sus controles, así que la vista no pierde el contexto.
function rerenderVisibleView(view){
  if(view==='dashboard')renderDashboard();
  if(view==='center')renderCenter();
  if(view==='pending')renderPending();
  if(view==='clients')renderClients();
}
document.querySelectorAll('.nav-item').forEach(button=>button.addEventListener('click',()=>{
  rerenderVisibleView(button.dataset.view);
}));

// Los controles se enlazaron al arrancar la aplicación. Al haber varias capas
// de compatibilidad, se vuelve a enlazar aquí la versión final para que ningún
// filtro pueda recuperar un renderizado antiguo.
['center-search','center-category','center-status','center-sort'].forEach(id=>{
  const control=$(id);
  if(!control)return;
  const finalControl=control.cloneNode(true);
  finalControl.value=control.value;
  control.replaceWith(finalControl);
  finalControl.addEventListener('input',()=>renderCenter());
  finalControl.addEventListener('change',()=>renderCenter());
});

// Algunos navegadores pueden conservar un listener antiguo durante el cambio
// de filtro. Este repintado se ejecuta al terminar todos los listeners y deja
// siempre las acciones con el formato único de la vista final.
document.addEventListener('input',event=>{
  if(['center-search','center-category','center-status','center-sort'].includes(event.target?.id))queueMicrotask(()=>renderCenter());
},true);
document.addEventListener('change',event=>{
  if(['center-search','center-category','center-status','center-sort'].includes(event.target?.id))queueMicrotask(()=>renderCenter());
},true);

// Normaliza también el resultado visible por si una rutina antigua vuelve a
// pintar la tabla después de los filtros. Así todas las vistas conservan la
// acción única «Editar / seguimiento».
function normalizeCenterRowActions(){
  const table=$('center-table');
  if(!table)return;
  table.querySelectorAll('tr').forEach(row=>{
    const cell=row.lastElementChild;
    const edit=cell?.querySelector('.edit-btn');
    if(!edit)return;
    cell.querySelectorAll('.done-btn,input[type="date"]').forEach(control=>control.remove());
    edit.textContent='Editar / seguimiento';
  });
}
normalizeCenterRowActions();
if($('center-table'))new MutationObserver(()=>queueMicrotask(normalizeCenterRowActions)).observe($('center-table'),{childList:true,subtree:true});
setInterval(normalizeCenterRowActions,250);
